mapper.update:
UPDATE knowledge_document SET version = #{job.documentVersion}, last_generation = #{job.indexGeneration},
    display_name = #{input.displayName}, content_type = #{job.contentType}, content_hash = #{job.contentHash},
    size_bytes = #{job.sizeBytes}, ingestion_job_id = #{job.jobId}, active_job_id = #{job.jobId}, status = 'RECEIVED',
    revision = revision + 1, updated_at = #{input.acceptedAt}
WHERE tenant_id = #{caller.tenantId} AND owner_id = #{caller.userId} AND document_id = #{input.documentId}
    AND lifecycle_ready = TRUE AND lifecycle = 'ACTIVE' AND revision = #{input.expectedRevision}
    AND revision < 2147483647 AND version < 2147483647 AND last_generation < 2147483647

mapper.select:
SELECT r.content_revision, r.display_name, r.content_type, r.size_bytes, r.content_hash, r.created_at
FROM knowledge_document_revision r JOIN knowledge_document d
    ON d.tenant_id = r.tenant_id AND d.owner_id = r.owner_id AND d.document_id = r.document_id
WHERE r.tenant_id = #{caller.tenantId} AND r.owner_id = #{caller.userId} AND r.document_id = #{id}
    AND d.lifecycle <> 'DELETED' AND d.lifecycle_ready = TRUE AND r.content_revision < #{before}
ORDER BY r.content_revision DESC LIMIT #{limit}

SELECT j.index_generation, j.document_version AS content_revision, j.job_id, j.processor_version, j.status,
    (d.published_job_id = j.job_id AND d.published_generation = j.index_generation AND d.published_version = j.document_version) IS TRUE AS is_current_publication,
    j.status = 'READY' AS was_published, j.error_code,
    (j.retryable = TRUE AND d.lifecycle = 'ACTIVE' AND d.active_job_id = j.job_id) IS TRUE AS retryable
FROM knowledge_ingestion j JOIN knowledge_document d
    ON d.tenant_id = j.tenant_id AND d.owner_id = j.owner_id AND d.document_id = j.document_id
WHERE j.tenant_id = #{caller.tenantId} AND j.owner_id = #{caller.userId} AND j.document_id = #{id}
    AND d.lifecycle <> 'DELETED' AND d.lifecycle_ready = TRUE AND j.index_generation < #{before}
ORDER BY j.index_generation DESC LIMIT #{limit}
